import{_ as t,o as a,c as o,aj as l}from"./chunks/framework.C6uXqnaX.js";const g=JSON.parse('{"title":"Add the localize package","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/i18n/add-package.md","filePath":"en/guide/i18n/add-package.md"}'),i={name:"en/guide/i18n/add-package.md"};function n(d,e,c,s,r,p){return a(),o("div",null,e[0]||(e[0]=[l('<h1 id="add-the-localize-package" tabindex="-1">Add the localize package <a class="header-anchor" href="#add-the-localize-package" aria-label="Permalink to &quot;Add the localize package&quot;">​</a></h1><p>To take advantage of the localization features of Angular, use the <a href="./cli" title="CLI Overview and Command Reference | Angular">Angular CLI</a> to add the <code>@angular/localize</code> package to your project.</p><p>To add the <code>@angular/localize</code> package, use the following command to update the <code>package.json</code> and TypeScript configuration files in your project.</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @angular/localize</span></span></code></pre></div><p>It adds <code>types: [&quot;@angular/localize&quot;]</code> in the TypeScript configuration files. It also adds line <code>/// &lt;reference types=&quot;@angular/localize&quot; /&gt;</code> at the top of the <code>main.ts</code> file which is the reference to the type definition.</p><div class="tip custom-block"><p class="custom-block-title">HELPFUL</p><p>For more information about <code>package.json</code> and <code>tsconfig.json</code> files, see <a href="./reference/configs/npm-packages" title="Workspace npm dependencies | Angular">Workspace npm dependencies</a> and <a href="https://www.typescriptlang.org/docs/handbook/tsconfig-json.html" title="TypeScript Configuration" target="_blank" rel="noreferrer">TypeScript Configuration</a>. To learn about Triple-slash Directives visit <a href="https://www.typescriptlang.org/docs/handbook/triple-slash-directives.html#-reference-types-" target="_blank" rel="noreferrer">TypeScript Handbook</a>.</p></div><p>If <code>@angular/localize</code> is not installed and you try to build a localized version of your project (for example, while using the <code>i18n</code> attributes in templates), the <a href="./cli" title="CLI Overview and Command Reference | Angular">Angular CLI</a> will generate an error, which would contain the steps that you can take to enable i18n for your project.</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">OPTION</th><th style="text-align:left;">DESCRIPTION</th><th style="text-align:left;">VALUE TYPE</th><th style="text-align:left;">DEFAULT VALUE</th></tr></thead><tbody><tr><td style="text-align:left;"><code>--project</code></td><td style="text-align:left;">The name of the project.</td><td style="text-align:left;"><code>string</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>--use-at-runtime</code></td><td style="text-align:left;">If set, then <code>$localize</code> can be used at runtime. Also <code>@angular/localize</code> gets included in the <code>dependencies</code> section of <code>package.json</code>, rather than <code>devDependencies</code>, which is the default.</td><td style="text-align:left;"><code>boolean</code></td><td style="text-align:left;"><code>false</code></td></tr></tbody></table><p>For more available options, see <code>ng add</code> in <a href="./cli" title="CLI Overview and Command Reference | Angular">Angular CLI</a>.</p><h2 id="what-s-next" tabindex="-1">What&#39;s next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next&quot;">​</a></h2><ul><li><a href="/en/guide/i18n/locale-id">Refer to locales by ID</a></li></ul>',12)]))}const u=t(i,[["render",n]]);export{g as __pageData,u as default};
